.ripple {
  position: absolute;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.6);
  transform: scale(0);
  animation: ripple-animation 0.6s ease-out;
  pointer-events: none;
}
@keyframes ripple-animation {
  to {
    transform: scale(4);
    opacity: 0;
  }
}

class RippleButton extends HTMLButtonElement {
  connectedCallback() {
    this.addEventListener('click', this.createRipple);
  }

  disconnectedCallback() {
    this.removeEventListener('click', this.createRipple);
  }

  createRipple = (event) => {
    // 创建波纹元素
    const ripple = document.createElement('span');
    ripple.classList.add('ripple');

    // 计算波纹的位置和大小
    const rect = this.getBoundingClientRect();
    const size = Math.max(rect.width, rect.height);
    const x = event.clientX - rect.left - size / 2;
    const y = event.clientY - rect.top - size / 2;

    // 设置波纹样式
    ripple.style.width = ripple.style.height = size + 'px';
    ripple.style.left = x + 'px';
    ripple.style.top = y + 'px';

    // 添加到按钮中
    this.appendChild(ripple);

    // 动画结束后移除波纹元素
    ripple.addEventListener('animationend', () => {
      ripple.remove();
    });
  }
}

// 注册自定义元素
customElements.define('ripple-button', RippleButton, { extends: 'button' });
